#include <iostream>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007LL;

int64 modPow(int64 base, int64 exponent) {
    int64 result = 1;
    base %= MOD;

    while (exponent > 0) {
        if (exponent & 1)
            result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 x, k;
    cin >> x >> k;

    if (x <= 0) {
        cout << 0 << '\n';
        return 0;
    }

    x %= MOD;
    int64 power = modPow(2, k);
    int64 factor = (2 * x - 1 + MOD) % MOD;
    int64 answer = (power * factor + 1) % MOD;

    cout << answer << '\n';
    return 0;
}

